private val StringSetSaver = listSaver<Set<String>, String>(
    save = { it.toList() },
    restore = { it.toSet() },
)

@Composable
private fun MedicationsListContent(
    patient: DemoPatient,
    onEditMedication: (DemoMedicationRecord) -> Unit,
) {
    val medications = patient.medications
    val canEdit = patient.status != "archived"

    var expandedIds by rememberSaveable(
        patient.id,
        medications.map { it.id }.joinToString(","),
        stateSaver = StringSetSaver,
    ) {
        mutableStateOf(
            if (medications.size <= 3) {
                medications.map { it.id }.toSet()
            } else {
                emptySet()
            }
        )
    }

    Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
        if (medications.size > 3) {
            val allExpanded = medications.isNotEmpty() && medications.all { it.id in expandedIds }
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.End,
            ) {
                TextButton(
                    onClick = {
                        expandedIds = if (allExpanded) {
                            emptySet()
                        } else {
                            medications.map { it.id }.toSet()
                        }
                    },
                    modifier = Modifier
                        .minimumTouchTarget()
                        .testTag("medicationsToggleAll"),
                ) {
                    Text(
                        text = stringResource(if (allExpanded) R.string.collapse_all else R.string.expand_all),
                    )
                }
            }
        }

        medications.forEach { med ->
            val isExpanded = med.id in expandedIds
            MedicationCard(
                med = med,
                isExpanded = isExpanded,
                canEdit = canEdit,
                onToggle = {
                    expandedIds = if (isExpanded) {
                        expandedIds - med.id
                    } else {
                        expandedIds + med.id
                    }
                },
                onEdit = { onEditMedication(med) },
            )
        }
    }
}

@Composable
private fun MedicationCard(
    med: DemoMedicationRecord,
    isExpanded: Boolean,
    canEdit: Boolean,
    onToggle: () -> Unit,
    onEdit: () -> Unit,
) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .testTag("medication-${med.id}"),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceContainerLow),
    ) {
        if (isExpanded) {
            Column(Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .minimumTouchTarget()
                        .testTag("medicationToggle-${med.id}")
                        .clickable(onClick = onToggle),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                    ) {
                        Icon(
                            imageVector = Icons.Default.KeyboardArrowUp,
                            contentDescription = stringResource(R.string.hide_details),
                            tint = MaterialTheme.colorScheme.onSurfaceVariant,
                            modifier = Modifier.size(20.dp),
                        )
                        Text(med.name, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)
                    }
                    MedicationStatusBadge(effectiveMedicationStatus(med.status, med.isNonCompliant))
                }
                FactRow(R.string.dosage, med.dosage)
                FactRow(R.string.route, med.route)
                FactRow(R.string.frequency, med.frequency)
                FactRow(R.string.start_date, med.startDate)
                FactRow(R.string.end_date, med.endDate)
                if (!med.adverseNotes.isNullOrBlank()) {
                    FactRow(R.string.adverse_effects, med.adverseNotes)
                }
                FactRow(R.string.notes, med.notes)
                if (canEdit) {
                    PencilEditButton(
                        contentDescription = stringResource(R.string.edit_medication),
                        tag = "editMedication-${med.id}",
                        onClick = onEdit,
                    )
                }
            }
        } else {
            val summaryText = listOfNotNull(
                med.dosage?.takeIf { it.isNotBlank() },
                med.frequency?.takeIf { it.isNotBlank() },
            ).joinToString(" · ")

            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .defaultMinSize(minHeight = 48.dp),
                contentAlignment = Alignment.CenterStart,
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .defaultMinSize(minHeight = 48.dp)
                        .testTag("medicationToggle-${med.id}")
                        .clickable(onClick = onToggle)
                        .padding(
                            start = 16.dp,
                            end = if (canEdit) 52.dp else 16.dp,
                            top = 8.dp,
                            bottom = 8.dp,
                        ),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    CollapsedMedicationRow(
                        name = med.name,
                        status = effectiveMedicationStatus(med.status, med.isNonCompliant),
                        summaryText = summaryText,
                    )
                }
                if (canEdit) {
                    PencilEditButton(
                        contentDescription = stringResource(R.string.edit_medication),
                        tag = "editMedication-${med.id}",
                        onClick = onEdit,
                    )
                }
            }
        }
    }
}

@Composable
private fun CollapsedMedicationRow(
    name: String,
    status: String,
    summaryText: String,
    modifier: Modifier = Modifier,
) {
    Layout(
        modifier = modifier,
        content = {
            Icon(
                imageVector = Icons.Default.KeyboardArrowDown,
                contentDescription = stringResource(R.string.show_details),
                tint = MaterialTheme.colorScheme.onSurfaceVariant,
                modifier = Modifier.size(20.dp),
            )
            Text(
                text = name,
                style = MaterialTheme.typography.titleMedium,
                fontWeight = FontWeight.Bold,
                maxLines = 1,
            )
            MedicationStatusBadge(status)
            if (summaryText.isNotBlank()) {
                Text(
                    text = summaryText,
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    maxLines = 1,
                )
            }
        },
    ) { measurables, constraints ->
        val spacing = 8.dp.roundToPx()
        val chevronPlaceable = measurables[0].measure(Constraints())
        val namePlaceable = measurables[1].measure(Constraints())
        val badgePlaceable = measurables[2].measure(Constraints())

        val fixedWidth = chevronPlaceable.width + spacing + namePlaceable.width + spacing + badgePlaceable.width
        val hasSummary = measurables.size > 3
        val summaryPlaceable = if (hasSummary) {
            val unconstrained = measurables[3].measure(Constraints())
            val availForSummary = constraints.maxWidth - fixedWidth - spacing
            if (availForSummary > 0 && unconstrained.width <= availForSummary) {
                unconstrained
            } else {
                null
            }
        } else {
            null
        }

        val totalWidth = if (summaryPlaceable != null) {
            fixedWidth + spacing + summaryPlaceable.width
        } else {
            fixedWidth
        }
        val height = maxOf(
            chevronPlaceable.height,
            namePlaceable.height,
            badgePlaceable.height,
            summaryPlaceable?.height ?: 0,
        )

        layout(totalWidth.coerceAtMost(constraints.maxWidth), height) {
            var x = 0
            chevronPlaceable.placeRelative(x, (height - chevronPlaceable.height) / 2)
            x += chevronPlaceable.width + spacing
            namePlaceable.placeRelative(x, (height - namePlaceable.height) / 2)
            x += namePlaceable.width + spacing
            badgePlaceable.placeRelative(x, (height - badgePlaceable.height) / 2)
            if (summaryPlaceable != null) {
                x += badgePlaceable.width + spacing
                summaryPlaceable.placeRelative(x, (height - summaryPlaceable.height) / 2)
            }
        }
